import{at as e,it as t,n,vt as r}from"./chunks/framework.BtDTgfNe.js";var i=JSON.parse(`{"title":"Float Literals - v6","description":"Learn about float literals in Textwire","frontmatter":{"title":"Float Literals - v6","description":"Learn about float literals in Textwire"},"headers":[],"relativePath":"language-elements/literals/float.md","filePath":"src/language-elements/literals/float.md","lastUpdated":1795359991000}`),a={name:`language-elements/literals/float.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="float-literals" tabindex="-1">Float Literals <a class="header-anchor" href="#float-literals" aria-label="Permalink to “Float Literals”">​</a></h1><p>You can use float literals and perform arithmetic operations with them. Example:</p><div class="language-textwire" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">textwire</span><pre class="shiki shiki-themes github-light catppuccin-mocha" style="--shiki-light:#24292e;--shiki-dark:#cdd6f4;--shiki-light-bg:#fff;--shiki-dark-bg:#1e1e2e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#94E2D5;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#89B4FA;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#94E2D5;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;">{{</span><span style="--shiki-light:#005CC5;--shiki-dark:#FAB387;"> 1.534</span><span style="--shiki-light:#c62739;--shiki-dark:#CBA6F7;"> + </span><span style="--shiki-light:#005CC5;--shiki-dark:#FAB387;">2.5</span><span style="--shiki-light:#005CC5;--shiki-light-font-style:inherit;--shiki-dark:#89B4FA;--shiki-dark-font-style:italic;"> }}</span><span style="--shiki-light:#24292E;--shiki-dark:#94E2D5;">&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#89B4FA;">span</span><span style="--shiki-light:#24292E;--shiki-dark:#94E2D5;">&gt;</span></span></code></pre></div><h2 id="follows-ieee-754-like-go" tabindex="-1">Follows IEEE 754 like Go <a class="header-anchor" href="#follows-ieee-754-like-go" aria-label="Permalink to “Follows IEEE 754 like Go”">​</a></h2><p>Overflow produces <code>+Inf</code> or <code>-Inf</code>, values too small to represent underflow to <code>0.0</code>, and invalid operations like <code>+Inf - +Inf</code> produce <code>NaN</code>. These special values are printed as <code>+Inf</code>, <code>-Inf</code>, and <code>NaN</code>.</p><h2 id="important-notes" tabindex="-1">Important Notes <a class="header-anchor" href="#important-notes" aria-label="Permalink to “Important Notes”">​</a></h2><ul><li><strong>Precision limit (IEEE 754).</strong> Floating-point numbers have ~15-17 digit precision. For example, <code>1234567890.1234567890</code> rounds to <code>1234567890.1234567</code>.</li><li><strong>Large numbers as strings.</strong> Keep large numbers as strings if you need exact precision.</li><li><strong>Division follows the operand types.</strong> Float division like <code>4.0 / 2.0</code> returns a float. Integer division like <code>4 / 2</code> returns an integer.</li><li><strong>Non-finite floats become <code>null</code> in JSON.</strong> <code>+Inf</code>, <code>-Inf</code>, and <code>NaN</code> are serialized as <code>null</code>.</li></ul>`,7)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};